    /**
     * Decifra um envelope v5. Erro `Utd{reason}` quando não dá (ver `UtdReason::retryable`).
     */
    suspend fun `decrypt`(`input`: DecryptInput): Decrypted
    
    fun `deviceId`(): kotlin.String
    
    /**
     * Cifra o payload interno v1 para a conversa. `member_uids` = membros ATUAIS (o servidor é a
     * fonte; o próprio usuário entra sempre para os meus outros aparelhos).
     */
    suspend fun `encrypt`(`convId`: kotlin.String, `memberUids`: List<kotlin.String>, `payloadJson`: kotlin.String): EncryptResult
    
    /**
     * Exporta chaves Megolm de entrada (JSON `ExportedRoomKey[]`) — vínculo web e celular novo.
     * O blob é SEGREDO: só sai por canal cifrado (ECIES do vínculo) ou cifrado por senha.
     */
    suspend fun `exportRoomKeys`(`filter`: ExportFilter): kotlin.ByteArray
    
    /**
     * Export cifrado por senha (formato padrão de export de chaves Matrix, PBKDF2) para
     * "salvar arquivo de chaves" manual. Não é usado no vínculo nem no backup.
     */
    suspend fun `exportRoomKeysWithPassphrase`(`passphrase`: kotlin.String): kotlin.String
    
    /**
     * Envia a métrica agregada ao servidor (`e2ee5_metrics`). Só contagens.
     */
    suspend fun `flushMetrics`()
    
    /**
     * Revoga um aparelho MEU (vinculado). Servidor apaga; rotaciono todas as conversas.
     */
    suspend fun `forgetDevice`(`deviceId`: kotlin.String): kotlin.UInt
    
    suspend fun `identityStatus`(`uid`: kotlin.String): IdentityStatus
    
    suspend fun `importRoomKeys`(`blob`: kotlin.ByteArray): ImportResult
    
    suspend fun `importRoomKeysWithPassphrase`(`data`: kotlin.String, `passphrase`: kotlin.String): ImportResult
    
    suspend fun `listDevices`(`uid`: kotlin.String): List<DeviceSummary>
    
    /**
     * Marca contato como verificado (após comparar os 60 dígitos de viva voz).
     */
    suspend fun `markVerified`(`uid`: kotlin.String)
    
    fun `metricsSnapshot`(): MetricsSnapshot
    
    /**
     * Mudança de membros: acompanha os atuais; se alguém SAIU, rotaciona já (quem sai não lê a
     * próxima). Entradas não precisam rotacionar (quem entra não recebe o passado: a sessão
     * é compartilhada a partir do índice atual).
     */
    suspend fun `onMembersChanged`(`convId`: kotlin.String, `memberUids`: List<kotlin.String>, `removedUids`: List<kotlin.String>)
    
    /**
     * Aceita a identidade ATUAL do contato (depois do aviso "código de segurança mudou").
     */
    suspend fun `pinIdentity`(`uid`: kotlin.String)
    
    /**
     * Força rotação da sessão Megolm de saída (ex.: alguém saiu, aparelho revogado).
     */
    suspend fun `rotateConversation`(`convId`: kotlin.String): kotlin.Boolean
    
    suspend fun `safetyNumber`(`uid`: kotlin.String): SafetyNumber
    
    /**
     * to-device cifrado Olm com evento `chatyy.*` (chave de ligação, SDP, relatório de UTD…).
     * Só chega a aparelhos ASSINADOS pelo dono. Nunca vai ao aparelho atual.
     */
    suspend fun `sendToDevice`(`eventType`: kotlin.String, `targets`: List<DeviceTarget>, `contentJson`: kotlin.String): SendToDeviceResult
    
    /**
     * Assina um aparelho MEU com a SSK (vínculo). `expected_ed25519` vem do canal seguro do
     * vínculo: se o servidor devolver outra chave para esse device_id, NÃO assina.
     */
    suspend fun `signDevice`(`deviceId`: kotlin.String, `expectedEd25519`: kotlin.String)
    
    /**
     * Uma rodada de `e2ee5_sync`: to-device + mudanças de aparelhos + contagem de OTK,
     * processa tudo e esvazia os pedidos pendentes (upload de chaves etc.).
     */
    suspend fun `sync`(): SyncResult
    
    /**
     * Variante em que o HOST já tem o corpo de `e2ee5_sync` (ex.: veio no push/WS).
     * Não avança cursores (o próximo `sync()` repete com segurança: Olm descarta duplicatas).
     */
    suspend fun `syncWith`(`syncDataJson`: kotlin.String): SyncResult
    
    /**
     * Chaves públicas deste aparelho (o vínculo QR e a tela de aparelhos usam).
     */
    suspend fun `thisDevice`(): DeviceSummary
    
    /**
     * Começa a acompanhar a lista de aparelhos destes usuários (membros das conversas E2EE).
     */
    suspend fun `trackUsers`(`uids`: List<kotlin.String>)
    
    fun `uid`(): kotlin.String
    
    /**
     * O usuário escaneou o QR do contato. Se as duas MSK conferem, marca o contato como
     * verificado (assinatura USK — exige ser o principal) e devolve `true`.
     */
    suspend fun `verifySafetyQr`(`uid`: kotlin.String, `scanned`: kotlin.String): kotlin.Boolean
    
    companion object
}

open class CryptoCore: Disposable, AutoCloseable, CryptoCoreInterface
{

    constructor(pointer: Pointer) {
        this.pointer = pointer
        this.cleanable = UniffiLib.CLEANER.register(this, UniffiCleanAction(pointer))
    }

    /**
     * This constructor can be used to instantiate a fake object. Only used for tests. Any
     * attempt to actually use an object constructed this way will fail as there is no
     * connected Rust object.
     */
    @Suppress("UNUSED_PARAMETER")
    constructor(noPointer: NoPointer) {
        this.pointer = null
        this.cleanable = UniffiLib.CLEANER.register(this, UniffiCleanAction(pointer))
    }

    protected val pointer: Pointer?
    protected val cleanable: UniffiCleaner.Cleanable

    private val wasDestroyed = AtomicBoolean(false)
    private val callCounter = AtomicLong(1)

    override fun destroy() {
        // Only allow a single call to this method.
        // TODO: maybe we should log a warning if called more than once?
        if (this.wasDestroyed.compareAndSet(false, true)) {
            // This decrement always matches the initial count of 1 given at creation time.
            if (this.callCounter.decrementAndGet() == 0L) {
                cleanable.clean()
            }
        }
    }

    @Synchronized
    override fun close() {
        this.destroy()
    }

    internal inline fun <R> callWithPointer(block: (ptr: Pointer) -> R): R {
        // Check and increment the call counter, to keep the object alive.
        // This needs a compare-and-set retry loop in case of concurrent updates.
        do {
            val c = this.callCounter.get()
            if (c == 0L) {
                throw IllegalStateException("${this.javaClass.simpleName} object has already been destroyed")
            }
            if (c == Long.MAX_VALUE) {
                throw IllegalStateException("${this.javaClass.simpleName} call counter would overflow")
            }
        } while (! this.callCounter.compareAndSet(c, c + 1L))
        // Now we can safely do the method call without the pointer being freed concurrently.
        try {
            return block(this.uniffiClonePointer())
        } finally {
            // This decrement always matches the increment we performed above.
            if (this.callCounter.decrementAndGet() == 0L) {
                cleanable.clean()
            }
        }
    }

    // Use a static inner class instead of a closure so as not to accidentally
    // capture `this` as part of the cleanable's action.
    private class UniffiCleanAction(private val pointer: Pointer?) : Runnable {
        override fun run() {
            pointer?.let { ptr ->
                uniffiRustCall { status ->
                    UniffiLib.INSTANCE.uniffi_chatyy_crypto_fn_free_cryptocore(ptr, status)
                }
            }
        }
    }

    fun uniffiClonePointer(): Pointer {
        return uniffiRustCall() { status ->
            UniffiLib.INSTANCE.uniffi_chatyy_crypto_fn_clone_cryptocore(pointer!!, status)
        }
    }

    
