                throw IllegalStateException("${this.javaClass.simpleName} call counter would overflow")
            }
        } while (! this.callCounter.compareAndSet(c, c + 1L))
        // Now we can safely do the method call without the pointer being freed concurrently.
        try {
            return block(this.uniffiClonePointer())
        } finally {
            // This decrement always matches the increment we performed above.
            if (this.callCounter.decrementAndGet() == 0L) {
                cleanable.clean()
            }
        }
    }

    // Use a static inner class instead of a closure so as not to accidentally
    // capture `this` as part of the cleanable's action.
    private class UniffiCleanAction(private val pointer: Pointer?) : Runnable {
        override fun run() {
            pointer?.let { ptr ->
                uniffiRustCall { status ->
                    UniffiLib.INSTANCE.uniffi_chatyy_crypto_fn_free_linkweb(ptr, status)
                }
            }
        }
    }

    fun uniffiClonePointer(): Pointer {
        return uniffiRustCall() { status ->
            UniffiLib.INSTANCE.uniffi_chatyy_crypto_fn_clone_linkweb(pointer!!, status)
        }
    }

    
    /**
     * Depois do `Granted` (bearer instalado no transporte do core): publica as chaves do aparelho.
     */
    @Throws(CoreException::class)
    @Suppress("ASSIGNED_BUT_NEVER_ACCESSED_VARIABLE")
    override suspend fun `completeUpload`(`core`: CryptoCore) {
        return uniffiRustCallAsync(
        callWithPointer { thisPtr ->
            UniffiLib.INSTANCE.uniffi_chatyy_crypto_fn_method_linkweb_complete_upload(
                thisPtr,
                FfiConverterTypeCryptoCore.lower(`core`),
            )
        },
        { future, callback, continuation -> UniffiLib.INSTANCE.ffi_chatyy_crypto_rust_future_poll_void(future, callback, continuation) },
        { future, continuation -> UniffiLib.INSTANCE.ffi_chatyy_crypto_rust_future_complete_void(future, continuation) },
        { future -> UniffiLib.INSTANCE.ffi_chatyy_crypto_rust_future_free_void(future) },
        // lift function
        { Unit },
        
        // Error FFI converter
        CoreException.ErrorHandler,
    )
    }

    override fun `linkId`(): kotlin.String {
            return FfiConverterString.lift(
    callWithPointer {
    uniffiRustCall() { _status ->
    UniffiLib.INSTANCE.uniffi_chatyy_crypto_fn_method_linkweb_link_id(
        it, _status)
}
    }
    )
    }
    

    
    /**
     * Uma rodada de leitura do rendezvous. `core` é obrigatório depois do `Hello`.
     */
    @Throws(CoreException::class)
    @Suppress("ASSIGNED_BUT_NEVER_ACCESSED_VARIABLE")
    override suspend fun `poll`(`core`: CryptoCore?) : LinkWebState {
        return uniffiRustCallAsync(
        callWithPointer { thisPtr ->
            UniffiLib.INSTANCE.uniffi_chatyy_crypto_fn_method_linkweb_poll(
                thisPtr,
                FfiConverterOptionalTypeCryptoCore.lower(`core`),
            )
        },
        { future, callback, continuation -> UniffiLib.INSTANCE.ffi_chatyy_crypto_rust_future_poll_rust_buffer(future, callback, continuation) },
        { future, continuation -> UniffiLib.INSTANCE.ffi_chatyy_crypto_rust_future_complete_rust_buffer(future, continuation) },
        { future -> UniffiLib.INSTANCE.ffi_chatyy_crypto_rust_future_free_rust_buffer(future) },
        // lift function
        { FfiConverterTypeLinkWebState.lift(it) },
        // Error FFI converter
        CoreException.ErrorHandler,
    )
    }

    override fun `qrPayload`(): kotlin.String {
            return FfiConverterString.lift(
    callWithPointer {
    uniffiRustCall() { _status ->
    UniffiLib.INSTANCE.uniffi_chatyy_crypto_fn_method_linkweb_qr_payload(
        it, _status)
}
    }
    )
    }
    

    
    /**
     * Depois do `Hello`: manda as chaves públicas do aparelho novo pelo canal.
     */
    @Throws(CoreException::class)
    @Suppress("ASSIGNED_BUT_NEVER_ACCESSED_VARIABLE")
    override suspend fun `sendDevice`(`core`: CryptoCore) {
        return uniffiRustCallAsync(
        callWithPointer { thisPtr ->
            UniffiLib.INSTANCE.uniffi_chatyy_crypto_fn_method_linkweb_send_device(
                thisPtr,
                FfiConverterTypeCryptoCore.lower(`core`),
            )
        },
        { future, callback, continuation -> UniffiLib.INSTANCE.ffi_chatyy_crypto_rust_future_poll_void(future, callback, continuation) },
        { future, continuation -> UniffiLib.INSTANCE.ffi_chatyy_crypto_rust_future_complete_void(future, continuation) },
        { future -> UniffiLib.INSTANCE.ffi_chatyy_crypto_rust_future_free_void(future) },
        // lift function
        { Unit },
        
        // Error FFI converter
        CoreException.ErrorHandler,
    )
    }

    

    
    companion object {
        
    /**
     * Cria o rendezvous e o QR. TTL do servidor: 2 min (renovar = novo `link_begin`).
     */
    @Throws(CoreException::class)
    @Suppress("ASSIGNED_BUT_NEVER_ACCESSED_VARIABLE")
     suspend fun `begin`(`transport`: HttpTransport) : LinkWeb {
        return uniffiRustCallAsync(
        UniffiLib.INSTANCE.uniffi_chatyy_crypto_fn_constructor_linkweb_begin(FfiConverterTypeHttpTransport.lower(`transport`),),
        { future, callback, continuation -> UniffiLib.INSTANCE.ffi_chatyy_crypto_rust_future_poll_pointer(future, callback, continuation) },
        { future, continuation -> UniffiLib.INSTANCE.ffi_chatyy_crypto_rust_future_complete_pointer(future, continuation) },
        { future -> UniffiLib.INSTANCE.ffi_chatyy_crypto_rust_future_free_pointer(future) },
        // lift function
        { FfiConverterTypeLinkWeb.lift(it) },
        // Error FFI converter
        CoreException.ErrorHandler,
    )
    }

        
    }
    
}

/**
 * @suppress
 */
public object FfiConverterTypeLinkWeb: FfiConverter<LinkWeb, Pointer> {

    override fun lower(value: LinkWeb): Pointer {
        return value.uniffiClonePointer()
    }

    override fun lift(value: Pointer): LinkWeb {
        return LinkWeb(value)
    }

    override fun read(buf: ByteBuffer): LinkWeb {
        // The Rust code always writes pointers as 8 bytes, and will
        // fail to compile if they don't fit.
        return lift(Pointer(buf.getLong()))
    }

    override fun allocationSize(value: LinkWeb) = 8UL

    override fun write(value: LinkWeb, buf: ByteBuffer) {
        // The Rust code always expects pointers written as 8 bytes,
        // and will fail to compile if they don't fit.
        buf.putLong(Pointer.nativeValue(lower(value)))
    }
}



