sealed class CoreException: kotlin.Exception() {
    
    /**
     * Não foi possível decifrar. `session_id` ajuda o host a pedir a chave / reagendar.
     */
    class Utd(
        
        val `reason`: UtdReason, 
        
        val `sessionId`: kotlin.String
        ) : CoreException() {
        override val message
            get() = "reason=${ `reason` }, sessionId=${ `sessionId` }"
    }
    
    /**
     * Entrada inválida do host (JSON, ids, tamanho). `field` diz qual.
     */
    class InvalidInput(
        
        val `field`: kotlin.String, 
        
        val `msg`: kotlin.String
        ) : CoreException() {
        override val message
            get() = "field=${ `field` }, msg=${ `msg` }"
    }
    
    /**
     * Falha de rede/transporte (o host não conseguiu falar com o servidor).
     */
    class Transport(
        
        val `msg`: kotlin.String
        ) : CoreException() {
        override val message
            get() = "msg=${ `msg` }"
    }
    
    /**
     * O servidor respondeu `success:false` com um código do contrato (§4.3).
     */
    class Server(
        
        val `status`: kotlin.UShort, 
        
        val `code`: kotlin.String
        ) : CoreException() {
        override val message
            get() = "status=${ `status` }, code=${ `code` }"
    }
    
    /**
     * Store de cripto (SQLite/IndexedDB) falhou ou senha errada.
     */
    class Store(
        
        val `msg`: kotlin.String
        ) : CoreException() {
        override val message
            get() = "msg=${ `msg` }"
    }
    
    /**
     * A trava entre processos não foi obtida a tempo (NSE x app).
     */
    class LockBusy(
        ) : CoreException() {
        override val message
            get() = ""
    }
    
    /**
     * Identidade de conta (MSK) ainda não existe / este aparelho não é o principal.
     */
    class Identity(
        
        val `msg`: kotlin.String
        ) : CoreException() {
        override val message
            get() = "msg=${ `msg` }"
    }
    
    /**
     * Um contato VERIFICADO trocou de identidade: o host pede confirmação e chama
     * `pin_identity(uid)` antes de reenviar. `uids` separados por vírgula.
     */
    class IdentityViolation(
        
        val `uids`: List<kotlin.String>
        ) : CoreException() {
        override val message
            get() = "uids=${ `uids` }"
    }
    
    /**
     * Mídia adulterada / hash não confere / info inválida.
     */
    class Media(
        
        val `msg`: kotlin.String
        ) : CoreException() {
        override val message
            get() = "msg=${ `msg` }"
    }
    
    /**
     * Vínculo QR: segredo, código ou chave não conferem; ou rendezvous expirou.
     */
    class Link(
        
        val `msg`: kotlin.String
        ) : CoreException() {
        override val message
            get() = "msg=${ `msg` }"
    }
    
    /**
     * Backup: chave de recuperação errada, versão ausente…
     */
    class Backup(
        
        val `msg`: kotlin.String
        ) : CoreException() {
        override val message
            get() = "msg=${ `msg` }"
    }
    
    /**
     * Erro interno inesperado (bug). Nunca contém conteúdo.
     */
    class Internal(
        
        val `msg`: kotlin.String
        ) : CoreException() {
        override val message
            get() = "msg=${ `msg` }"
    }
    

    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<CoreException> {
        override fun lift(error_buf: RustBuffer.ByValue): CoreException = FfiConverterTypeCoreError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeCoreError : FfiConverterRustBuffer<CoreException> {
    override fun read(buf: ByteBuffer): CoreException {
        

        return when(buf.getInt()) {
            1 -> CoreException.Utd(
                FfiConverterTypeUtdReason.read(buf),
                FfiConverterString.read(buf),
                )
            2 -> CoreException.InvalidInput(
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                )
            3 -> CoreException.Transport(
                FfiConverterString.read(buf),
                )
            4 -> CoreException.Server(
                FfiConverterUShort.read(buf),
                FfiConverterString.read(buf),
                )
            5 -> CoreException.Store(
                FfiConverterString.read(buf),
                )
            6 -> CoreException.LockBusy()
            7 -> CoreException.Identity(
                FfiConverterString.read(buf),
                )
            8 -> CoreException.IdentityViolation(
                FfiConverterSequenceString.read(buf),
                )
            9 -> CoreException.Media(
                FfiConverterString.read(buf),
                )
            10 -> CoreException.Link(
                FfiConverterString.read(buf),
                )
            11 -> CoreException.Backup(
                FfiConverterString.read(buf),
                )
            12 -> CoreException.Internal(
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: CoreException): ULong {
        return when(value) {
            is CoreException.Utd -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterTypeUtdReason.allocationSize(value.`reason`)
                + FfiConverterString.allocationSize(value.`sessionId`)
            )
            is CoreException.InvalidInput -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`field`)
                + FfiConverterString.allocationSize(value.`msg`)
            )
            is CoreException.Transport -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`msg`)
            )
            is CoreException.Server -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterUShort.allocationSize(value.`status`)
                + FfiConverterString.allocationSize(value.`code`)
            )
            is CoreException.Store -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`msg`)
            )
            is CoreException.LockBusy -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is CoreException.Identity -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`msg`)
            )
            is CoreException.IdentityViolation -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterSequenceString.allocationSize(value.`uids`)
            )
            is CoreException.Media -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`msg`)
            )
            is CoreException.Link -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`msg`)
            )
            is CoreException.Backup -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`msg`)
            )
            is CoreException.Internal -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`msg`)
            )
        }
    }

    override fun write(value: CoreException, buf: ByteBuffer) {
        when(value) {
            is CoreException.Utd -> {
                buf.putInt(1)
                FfiConverterTypeUtdReason.write(value.`reason`, buf)
                FfiConverterString.write(value.`sessionId`, buf)
                Unit
            }
            is CoreException.InvalidInput -> {
                buf.putInt(2)
                FfiConverterString.write(value.`field`, buf)
                FfiConverterString.write(value.`msg`, buf)
                Unit
            }
            is CoreException.Transport -> {
                buf.putInt(3)
                FfiConverterString.write(value.`msg`, buf)
                Unit
            }
            is CoreException.Server -> {
                buf.putInt(4)
                FfiConverterUShort.write(value.`status`, buf)
                FfiConverterString.write(value.`code`, buf)
                Unit
            }
            is CoreException.Store -> {
                buf.putInt(5)
                FfiConverterString.write(value.`msg`, buf)
                Unit
            }
            is CoreException.LockBusy -> {
                buf.putInt(6)
                Unit
            }
            is CoreException.Identity -> {
                buf.putInt(7)
                FfiConverterString.write(value.`msg`, buf)
                Unit
            }
            is CoreException.IdentityViolation -> {
                buf.putInt(8)
                FfiConverterSequenceString.write(value.`uids`, buf)
                Unit
            }
            is CoreException.Media -> {
                buf.putInt(9)
                FfiConverterString.write(value.`msg`, buf)
                Unit
            }
            is CoreException.Link -> {
                buf.putInt(10)
                FfiConverterString.write(value.`msg`, buf)
                Unit
            }
            is CoreException.Backup -> {
                buf.putInt(11)
                FfiConverterString.write(value.`msg`, buf)
                Unit
            }
            is CoreException.Internal -> {
                buf.putInt(12)
                FfiConverterString.write(value.`msg`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}



